import { DrillDownBreadcrumbConfig } from 'pages/pillars/ValueCreation/hooks/useDrillDownBreadcrumb';
import { hasDrillDownSpecificFilterValue } from 'pages/pillars/ValueCreation/utils/drillDownBreadcrumbUtils';

import {
  buildCommercialDrillDownClearPatch,
  COMMERCIAL_DRILL_DOWN_DIMENSION_KEYS,
  type CommercialDrillDownDimensionKey,
} from '../commercialResultsClearDrillDown';
import {
  COMMERCIAL_RESULTS_PAGE_NAME,
  CR_WATERFALL_RESET_EVENT,
} from './index';

export const COMMERCIAL_RESULTS_BREADCRUMB_CONFIG: DrillDownBreadcrumbConfig<CommercialDrillDownDimensionKey> =
  {
    pageName: COMMERCIAL_RESULTS_PAGE_NAME,
    goldenPathOrder: COMMERCIAL_DRILL_DOWN_DIMENSION_KEYS,
    navOrderParam: 'nav_cr_order',
    resetEvent: CR_WATERFALL_RESET_EVENT,
    hasSpecificValue: hasDrillDownSpecificFilterValue,
    buildClearPatch: (defaults, keysToClean) =>
      buildCommercialDrillDownClearPatch(defaults, keysToClean),
  };
